def choose_move(observation):
    sx = observation.get("self_position", (0, 0))[0]
    sy = observation.get("self_position", (0, 0))[1]
    ox = observation.get("opponent_position", (0, 0))[0]
    oy = observation.get("opponent_position", (0, 0))[1]
    env = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    resources = observation.get("resources") or []
    unclaimed_cells = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []
    role = observation.get("self_role", "pursuer")

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    if env == "pursuit_evasion":
        if role == "pursuer":
            return move_towards(ox, oy)
        else:
            return move_towards(ox, oy)

    elif env == "territory_control":
        targets = unclaimed_cells or opponent_territory
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best[0], best[1])

    elif resources:
        best_res = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best_res[0], best_res[1])
    else:
        # fallback to move towards opponent
        return move_towards(ox, oy)

